import type { CSSProperties, ReactNode } from "react";

import { DocsLandingEffects } from "@/registry/default/docs-landing/docs-landing-effects";
import { InstallCommand } from "@/registry/default/docs-landing/install-command";

import styles from "./docs-landing.module.css";

export type DocsLink = {
  href: string;
  label: string;
  external?: boolean;
};

export type DocsLandingProps = {
  children: ReactNode;
  name: string;
  brandMark?: ReactNode;
  className?: string;
  footerLinks?: readonly DocsLink[];
  footerNote?: ReactNode;
  homeHref?: string;
  navigation?: readonly DocsLink[];
  repository?: DocsLink;
  style?: CSSProperties;
  version?: string;
};

export type DocsHeroProps = {
  actions?: readonly (DocsLink & { kind?: "primary" | "secondary" })[];
  description: ReactNode;
  eyebrow: ReactNode;
  id?: string;
  installCommand?: string;
  nextHref?: string;
  nextLabel?: string;
  title: ReactNode;
  visual?: ReactNode;
};

export type DocsStat = {
  label: string;
  value: string;
  href?: string;
};

export type DocsSectionProps = {
  children?: ReactNode;
  action?: DocsLink;
  description?: ReactNode;
  eyebrow: ReactNode;
  id?: string;
  index?: string;
  layout?: "copy-first" | "stacked" | "visual-first";
  title: ReactNode;
  tone?: "blue" | "coral" | "dark" | "lime" | "paper";
};

export type DocsTimelineItem = {
  date: string;
  description: ReactNode;
  href?: string;
  title: string;
};

const classes = (...values: (false | string | undefined)[]) =>
  values.filter(Boolean).join(" ");

const linkProps = (link: DocsLink) =>
  link.external
    ? ({ rel: "noreferrer", target: "_blank" } as const)
    : undefined;

const DocsActionLink = ({
  kind = "secondary",
  link,
}: {
  kind?: "primary" | "secondary";
  link: DocsLink;
}) => (
  <a
    className={kind === "primary" ? styles.primaryAction : styles.textAction}
    href={link.href}
    {...linkProps(link)}
  >
    {link.label}
    <span aria-hidden="true" className={styles.actionLine} />
  </a>
);

export const DocsLanding = ({
  brandMark,
  children,
  className,
  footerLinks = [],
  footerNote,
  homeHref = "/",
  name,
  navigation = [],
  repository,
  style,
  version,
}: DocsLandingProps) => (
  <DocsLandingEffects className={classes(styles.root, className)} style={style}>
    <header className={styles.header}>
      <div className={styles.headerInner}>
        <a aria-label={`${name} home`} className={styles.brand} href={homeHref}>
          {brandMark ? (
            <span className={styles.brandMark}>{brandMark}</span>
          ) : null}
          <span>{name}</span>
          {version ? <code>{version}</code> : null}
        </a>

        <nav aria-label="Primary navigation" className={styles.navigation}>
          {navigation.map((link) => (
            <a
              href={link.href}
              key={`${link.href}-${link.label}`}
              {...linkProps(link)}
            >
              {link.label}
            </a>
          ))}
          {repository ? (
            <a
              className={styles.repositoryLink}
              href={repository.href}
              {...linkProps({ ...repository, external: true })}
            >
              {repository.label}
            </a>
          ) : null}
        </nav>
      </div>
    </header>

    {children}

    <footer className={styles.footer}>
      <div>
        <a className={styles.brand} href={homeHref}>
          {brandMark ? (
            <span className={styles.brandMark}>{brandMark}</span>
          ) : null}
          <span>{name}</span>
        </a>
        {footerNote ? <p>{footerNote}</p> : null}
      </div>
      {footerLinks.length > 0 ? (
        <nav aria-label="Footer navigation">
          {footerLinks.map((link) => (
            <a
              href={link.href}
              key={`${link.href}-${link.label}`}
              {...linkProps(link)}
            >
              {link.label}
            </a>
          ))}
        </nav>
      ) : null}
    </footer>
  </DocsLandingEffects>
);

export const DocsHero = ({
  actions = [],
  description,
  eyebrow,
  id = "overview",
  installCommand,
  nextHref,
  nextLabel = "Next section",
  title,
  visual,
}: DocsHeroProps) => (
  <section
    className={styles.hero}
    data-docs-hero
    data-has-visual={visual ? "true" : "false"}
    id={id}
  >
    <div className={styles.heroCopy}>
      <p className={styles.eyebrow} data-docs-hero-reveal>
        {eyebrow}
      </p>
      <h1 data-docs-hero-reveal>{title}</h1>
      <div className={styles.heroDescription} data-docs-hero-reveal>
        {description}
      </div>
      {actions.length > 0 ? (
        <div className={styles.heroActions} data-docs-hero-reveal>
          {actions.map((action) => (
            <DocsActionLink
              kind={action.kind}
              key={`${action.href}-${action.label}`}
              link={action}
            />
          ))}
        </div>
      ) : null}
      {installCommand ? (
        <div data-docs-hero-reveal>
          <InstallCommand command={installCommand} />
        </div>
      ) : null}
    </div>

    {visual ? (
      <div className={styles.heroVisual} data-docs-float="14" data-docs-visual>
        {visual}
      </div>
    ) : null}

    {nextHref ? (
      <a className={styles.scrollCue} href={nextHref}>
        <span>{nextLabel}</span>
        <span aria-hidden="true" className={styles.scrollGlyph} />
      </a>
    ) : null}
  </section>
);

export const DocsStatStrip = ({
  ariaLabel = "Project activity",
  items,
}: {
  ariaLabel?: string;
  items: readonly DocsStat[];
}) => (
  <section
    aria-label={ariaLabel}
    className={styles.statStrip}
    data-docs-section
  >
    <ul>
      {items.map((item) => (
        <li data-docs-reveal key={item.label}>
          {item.href ? (
            <a href={item.href} rel="noreferrer" target="_blank">
              <strong>{item.value}</strong>
              <span>{item.label}</span>
            </a>
          ) : (
            <>
              <strong>{item.value}</strong>
              <span>{item.label}</span>
            </>
          )}
        </li>
      ))}
    </ul>
    <span aria-hidden="true" data-docs-rule />
  </section>
);

export const DocsSection = ({
  action,
  children,
  description,
  eyebrow,
  id,
  index,
  layout = "copy-first",
  title,
  tone = "dark",
}: DocsSectionProps) => (
  <section
    className={styles.section}
    data-docs-section
    data-layout={layout}
    data-tone={tone}
    id={id}
  >
    <div className={styles.sectionCopy} data-docs-reveal>
      <div className={styles.sectionKicker}>
        {index ? <strong>{index}</strong> : null}
        <span>{eyebrow}</span>
      </div>
      <h2>{title}</h2>
      {description ? (
        <div className={styles.sectionDescription}>{description}</div>
      ) : null}
      {action ? <DocsActionLink link={action} /> : null}
    </div>

    {children ? (
      <div className={styles.sectionVisual} data-docs-reveal>
        {children}
      </div>
    ) : null}
    <span aria-hidden="true" data-docs-rule />
  </section>
);

export const DocsDemoFrame = ({
  children,
  label,
  meta,
}: {
  children: ReactNode;
  label: string;
  meta?: ReactNode;
}) => (
  <div className={styles.demoFrame} data-docs-float="8">
    <header>
      <span>{label}</span>
      {meta ? <span>{meta}</span> : null}
    </header>
    <div className={styles.demoBody}>{children}</div>
  </div>
);

export const DocsTimeline = ({
  description,
  eyebrow,
  id,
  items,
  title,
}: {
  description?: ReactNode;
  eyebrow: ReactNode;
  id?: string;
  items: readonly DocsTimelineItem[];
  title: ReactNode;
}) => (
  <section className={styles.timeline} data-docs-section id={id}>
    <header data-docs-reveal>
      <span>{eyebrow}</span>
      <h2>{title}</h2>
      {description ? <div>{description}</div> : null}
    </header>
    <ol>
      {items.map((item) => (
        <li data-docs-reveal key={`${item.date}-${item.title}`}>
          {item.href ? (
            <a href={item.href} rel="noreferrer" target="_blank">
              <time>{item.date}</time>
              <strong>{item.title}</strong>
              <div>{item.description}</div>
            </a>
          ) : (
            <div>
              <time>{item.date}</time>
              <strong>{item.title}</strong>
              <div>{item.description}</div>
            </div>
          )}
        </li>
      ))}
    </ol>
    <span aria-hidden="true" data-docs-rule />
  </section>
);

export const DocsFinalCta = ({
  action,
  decoration,
  description,
  eyebrow,
  installCommand,
  title,
}: {
  action: DocsLink;
  decoration?: ReactNode;
  description: ReactNode;
  eyebrow: ReactNode;
  installCommand?: string;
  title: ReactNode;
}) => (
  <section className={styles.finalCta} data-docs-section>
    <div className={styles.finalCopy} data-docs-reveal>
      <span>{eyebrow}</span>
      <h2>{title}</h2>
      <div>{description}</div>
      <div className={styles.finalActions}>
        <DocsActionLink kind="primary" link={action} />
        {installCommand ? (
          <InstallCommand command={installCommand} compact />
        ) : null}
      </div>
    </div>
    {decoration ? (
      <div
        aria-hidden="true"
        className={styles.finalDecoration}
        data-docs-float="10"
        data-docs-reveal
      >
        {decoration}
      </div>
    ) : null}
    <span aria-hidden="true" data-docs-rule />
  </section>
);

export { InstallCommand };

"use client";

import type { CSSProperties, ReactNode } from "react";

import { useLayoutEffect, useRef } from "react";

import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

type DocsLandingEffectsProps = {
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
};

export const DocsLandingEffects = ({
  children,
  className,
  style,
}: DocsLandingEffectsProps) => {
  const rootRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    gsap.registerPlugin(ScrollTrigger);

    const media = gsap.matchMedia();
    const context = gsap.context(() => {
      media.add("(prefers-reduced-motion: no-preference)", () => {
        const hero = root.querySelector<HTMLElement>("[data-docs-hero]");
        if (hero) {
          const heroCopy = hero.querySelectorAll<HTMLElement>(
            "[data-docs-hero-reveal]",
          );
          const heroVisual =
            hero.querySelector<HTMLElement>("[data-docs-visual]");
          const timeline = gsap.timeline({
            defaults: { duration: 0.76, ease: "power3.out" },
          });

          timeline.from(heroCopy, {
            autoAlpha: 0,
            stagger: 0.09,
            y: 24,
          });

          if (heroVisual) {
            timeline.from(
              heroVisual,
              {
                autoAlpha: 0,
                clipPath: "inset(0 0 100% 0)",
                duration: 1,
                ease: "expo.out",
                onComplete: () =>
                  gsap.set(heroVisual, { clearProps: "clipPath" }),
              },
              0.16,
            );
          }
        }

        const sections = gsap.utils.toArray<HTMLElement>(
          "[data-docs-section]",
          root,
        );

        for (const section of sections) {
          const targets =
            section.querySelectorAll<HTMLElement>("[data-docs-reveal]");
          if (targets.length > 0) {
            gsap.from(targets, {
              autoAlpha: 0,
              duration: 0.78,
              ease: "power3.out",
              scrollTrigger: {
                invalidateOnRefresh: true,
                once: true,
                start: "top 76%",
                trigger: section,
              },
              stagger: 0.1,
              y: 28,
            });
          }

          const rule = section.querySelector<HTMLElement>("[data-docs-rule]");
          if (rule) {
            gsap.fromTo(
              rule,
              { scaleX: 0, transformOrigin: "left center" },
              {
                ease: "none",
                scaleX: 1,
                scrollTrigger: {
                  end: "top 34%",
                  scrub: 0.7,
                  start: "top 94%",
                  trigger: section,
                },
              },
            );
          }
        }
      });

      media.add(
        "(prefers-reduced-motion: no-preference) and (hover: hover) and (pointer: fine)",
        () => {
          const floating = [
            ...root.querySelectorAll<HTMLElement>("[data-docs-float]"),
          ];
          if (floating.length === 0) return;

          const movers = floating.map((target) => ({
            moveX: gsap.quickTo(target, "x", {
              duration: 0.55,
              ease: "power3.out",
            }),
            moveY: gsap.quickTo(target, "y", {
              duration: 0.55,
              ease: "power3.out",
            }),
            target,
          }));

          const move = (event: PointerEvent) => {
            const x = event.clientX / window.innerWidth - 0.5;
            const y = event.clientY / window.innerHeight - 0.5;

            for (const mover of movers) {
              const strength = Number(mover.target.dataset.docsFloat ?? 12);
              mover.moveX(x * strength);
              mover.moveY(y * strength);
            }
          };

          const reset = () => {
            for (const mover of movers) {
              mover.moveX(0);
              mover.moveY(0);
            }
          };

          root.addEventListener("pointerleave", reset);
          root.addEventListener("pointermove", move);

          return () => {
            root.removeEventListener("pointerleave", reset);
            root.removeEventListener("pointermove", move);
            gsap.killTweensOf(floating);
            gsap.set(floating, { clearProps: "transform" });
          };
        },
      );
    }, root);

    return () => {
      media.revert();
      context.revert();
    };
  }, []);

  return (
    <div className={className} ref={rootRef} style={style}>
      {children}
    </div>
  );
};

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import styles from "./docs-landing.module.css";

type CopyState = "copied" | "failed" | "idle";

type InstallCommandProps = {
  command: string;
  className?: string;
  compact?: boolean;
};

const fallbackCopy = (command: string) => {
  const input = document.createElement("textarea");
  input.value = command;
  input.setAttribute("readonly", "");
  input.style.opacity = "0";
  input.style.position = "fixed";

  try {
    document.body.append(input);
    input.select();
    return document.execCommand("copy");
  } catch {
    return false;
  } finally {
    input.remove();
  }
};

const classes = (...values: (false | string | undefined)[]) =>
  values.filter(Boolean).join(" ");

const copyLabel = (copyState: CopyState) => {
  if (copyState === "copied") return "Copied";
  if (copyState === "failed") return "Copy failed";
  return "Copy";
};

const liveMessage = (copyState: CopyState) => {
  if (copyState === "copied") return "Install command copied";
  if (copyState === "failed") return "Couldn't copy the install command";
  return "";
};

export const InstallCommand = ({
  className,
  command,
  compact = false,
}: InstallCommandProps) => {
  const [copyState, setCopyState] = useState<CopyState>("idle");
  const resetTimer = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined,
  );

  useEffect(
    () => () => {
      clearTimeout(resetTimer.current);
    },
    [],
  );

  const copy = useCallback(async () => {
    let copied = false;

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(command);
        copied = true;
      }
    } catch {
      copied = false;
    }

    if (!copied) copied = fallbackCopy(command);

    setCopyState(copied ? "copied" : "failed");
    clearTimeout(resetTimer.current);
    resetTimer.current = setTimeout(() => setCopyState("idle"), 1800);
  }, [command]);

  return (
    <button
      aria-label={`Copy install command: ${command}`}
      className={classes(
        styles.installCommand,
        compact && styles.installCommandCompact,
        className,
      )}
      onClick={copy}
      type="button"
    >
      <span aria-hidden="true" className={styles.installPrompt}>
        $
      </span>
      <code>{command}</code>
      <span aria-hidden="true" className={styles.installCopy}>
        {copyLabel(copyState)}
      </span>
      <span aria-live="polite" className={styles.screenReaderOnly}>
        {liveMessage(copyState)}
      </span>
    </button>
  );
};

.root {
  --docs-accent: #ff6542;
  --docs-blue: #3157ff;
  --docs-canvas: #11100e;
  --docs-foreground: #f2ede3;
  --docs-ink: #151411;
  --docs-lime: #c8ff5a;
  --docs-line: #37332d;
  --docs-muted: #aaa298;
  --docs-paper: #f2ede3;
  --docs-paper-bright: #fffdf7;
  --docs-surface: #191714;
  background: var(--docs-canvas);
  color: var(--docs-foreground);
  color-scheme: dark;
  font-family:
    var(--font-docs-sans), Inter, ui-sans-serif, system-ui, sans-serif;
  min-height: 100svh;
  overflow: clip;
}

.root,
.root *,
.root *::after,
.root *::before {
  box-sizing: border-box;
}

.root a {
  color: inherit;
  text-decoration: none;
}

.root button,
.root input,
.root textarea {
  font: inherit;
}

.root code,
.root pre {
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
}

.root h1,
.root h2,
.root p {
  margin: 0;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 3px solid var(--docs-lime);
  outline-offset: 4px;
}

.root ::selection {
  background: var(--docs-lime);
  color: var(--docs-ink);
}

.header {
  backdrop-filter: blur(18px);
  background: color-mix(in srgb, var(--docs-canvas) 88%, transparent);
  border-bottom: 1px solid var(--docs-line);
  position: sticky;
  top: 0;
  z-index: 40;
}

.headerInner {
  align-items: center;
  display: flex;
  height: 68px;
  justify-content: space-between;
  margin: 0 auto;
  max-width: 1600px;
  padding: 0 clamp(1.25rem, 4vw, 4rem);
}

.brand {
  align-items: center;
  display: inline-flex;
  font-size: 0.95rem;
  font-weight: 720;
  gap: 0.68rem;
  letter-spacing: -0.025em;
  white-space: nowrap;
}

.brandMark {
  align-items: center;
  display: inline-flex;
  height: 34px;
  justify-content: center;
  width: 34px;
}

.brandMark > * {
  height: 100%;
  width: 100%;
}

.brand code {
  border-left: 1px solid var(--docs-line);
  color: var(--docs-muted);
  font-size: 0.65rem;
  font-weight: 550;
  margin-left: 0.15rem;
  padding-left: 0.8rem;
}

.navigation {
  align-items: center;
  display: flex;
  font-size: 0.78rem;
  font-weight: 650;
  gap: clamp(1rem, 2.4vw, 2.2rem);
}

.navigation > a {
  align-items: center;
  display: inline-flex;
  min-height: 44px;
  position: relative;
}

.navigation > a:not(.repositoryLink)::after {
  background: currentColor;
  bottom: 7px;
  content: "";
  height: 1px;
  left: 0;
  position: absolute;
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 180ms ease;
  width: 100%;
}

.navigation > a:not(.repositoryLink):hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.repositoryLink {
  border: 1px solid var(--docs-foreground);
  padding: 0 1rem;
  transition:
    background 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}

.repositoryLink:hover {
  background: var(--docs-foreground);
  color: var(--docs-ink);
  transform: translateY(-2px);
}

.hero {
  align-items: center;
  border-inline: 1px solid var(--docs-line);
  display: grid;
  gap: clamp(2.5rem, 5vw, 6.5rem);
  grid-template-columns: minmax(0, 0.88fr) minmax(480px, 1.12fr);
  margin: 0 auto;
  max-width: 1600px;
  min-height: calc(100svh - 68px);
  padding: clamp(4rem, 8vh, 7rem) clamp(1.5rem, 4vw, 4rem);
  position: relative;
}

.hero[data-has-visual="false"] {
  grid-template-columns: minmax(0, 780px);
}

.hero::before {
  background: var(--docs-line);
  content: "";
  height: 1px;
  inset: auto clamp(1.5rem, 4vw, 4rem) 4.4rem;
  opacity: 0.7;
  position: absolute;
}

.heroCopy {
  max-width: 680px;
  padding-left: clamp(0rem, 2vw, 2rem);
  position: relative;
  z-index: 2;
}

.eyebrow {
  color: var(--docs-muted);
  font-size: 0.73rem;
  font-weight: 680;
  letter-spacing: 0.045em;
  margin-bottom: clamp(1.5rem, 3vh, 2.4rem) !important;
  text-transform: uppercase;
}

.hero h1 {
  font-size: clamp(4rem, 6.4vw, 7.3rem);
  font-weight: 690;
  letter-spacing: -0.075em;
  line-height: 0.9;
  text-wrap: balance;
}

.hero h1 em,
.section h2 em,
.finalCta h2 em {
  color: var(--docs-accent);
  font-family:
    var(--font-docs-serif), "Iowan Old Style", "Palatino Linotype", serif;
  font-weight: 400;
  letter-spacing: -0.045em;
}

.heroDescription {
  color: var(--docs-muted);
  font-size: clamp(1.02rem, 1.3vw, 1.2rem);
  line-height: 1.62;
  margin-top: clamp(1.5rem, 3.2vh, 2.35rem);
  max-width: 590px;
}

.heroDescription code {
  color: var(--docs-foreground);
  font-size: 0.9em;
}

.sectionDescription code {
  color: var(--section-foreground);
  font-size: 0.9em;
}

.heroActions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem 1.25rem;
  margin-top: 1.9rem;
}

.primaryAction,
.textAction {
  align-items: center;
  display: inline-flex;
  font-size: 0.82rem;
  font-weight: 700;
  min-height: 46px;
  position: relative;
}

.primaryAction {
  background: var(--docs-foreground);
  color: var(--docs-ink) !important;
  padding: 0 1.15rem;
  transition:
    background 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.primaryAction:hover {
  background: var(--docs-lime);
  box-shadow: 7px 7px 0 var(--docs-accent);
  transform: translate(-2px, -2px);
}

.textAction {
  color: var(--section-muted, var(--docs-muted));
}

.actionLine {
  background: currentColor;
  bottom: 5px;
  height: 1px;
  left: 0;
  position: absolute;
  transform: scaleX(0.35);
  transform-origin: left;
  transition: transform 180ms ease;
  width: 100%;
}

.textAction:hover .actionLine {
  transform: scaleX(1);
}

.installCommand {
  align-items: center;
  background: transparent;
  border: 1px solid var(--section-line, var(--docs-line));
  color: inherit;
  cursor: pointer;
  display: inline-flex;
  gap: 0.62rem;
  margin-top: 0.85rem;
  max-width: 100%;
  min-height: 44px;
  padding: 0.62rem 0.76rem;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}

.installCommand:hover {
  background: color-mix(in srgb, currentColor 7%, transparent);
  border-color: currentColor;
  transform: translateY(-2px);
}

.installCommand code {
  font-size: 0.7rem;
  font-weight: 580;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.installPrompt {
  color: var(--section-accent, var(--docs-lime));
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  font-size: 0.8rem;
  font-weight: 800;
}

.installCopy {
  border-left: 1px solid var(--section-line, var(--docs-line));
  color: var(--section-muted, var(--docs-muted));
  font-size: 0.63rem;
  margin-left: 0.15rem;
  min-width: 4.5rem;
  padding-left: 0.65rem;
  text-align: left;
}

.installCommandCompact {
  margin-top: 0;
}

.screenReaderOnly {
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.heroVisual {
  align-items: stretch;
  align-self: center;
  background: var(--docs-surface);
  border: 1px solid var(--docs-line);
  box-shadow: 14px 16px 0 var(--docs-accent);
  display: flex;
  justify-content: stretch;
  min-height: clamp(470px, 62vh, 690px);
  position: relative;
  transform: rotate(-0.75deg);
  z-index: 1;
}

.heroVisual::before {
  background: var(--docs-lime);
  content: "";
  height: 4px;
  inset: -1px -1px auto;
  position: absolute;
  z-index: 2;
}

.heroVisual > * {
  flex: 1;
  min-width: 0;
}

.scrollCue {
  align-items: center;
  bottom: 1.2rem;
  color: var(--docs-muted) !important;
  display: flex;
  font-size: 0.68rem;
  gap: 0.65rem;
  left: 50%;
  min-height: 44px;
  position: absolute;
  transform: translateX(-50%);
}

.scrollGlyph {
  border-bottom: 1px solid currentColor;
  border-right: 1px solid currentColor;
  height: 8px;
  transform: rotate(45deg);
  width: 8px;
}

.statStrip {
  border: 1px solid var(--docs-line);
  margin: 0 auto;
  max-width: 1600px;
  position: relative;
}

.statStrip ul {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  list-style: none;
  margin: 0;
  padding: 0;
}

.statStrip li {
  border-right: 1px solid var(--docs-line);
  min-height: 116px;
}

.statStrip li:last-child {
  border-right: 0;
}

.statStrip li > a,
.statStrip li > :not(a),
.statStrip li {
  align-content: center;
}

.statStrip li > a {
  display: grid;
  height: 100%;
  padding: 1.35rem clamp(1.25rem, 3vw, 2.4rem);
  transition: background 160ms ease;
}

.statStrip li > a:hover {
  background: var(--docs-surface);
}

.statStrip li:not(:has(> a)) {
  padding: 1.35rem clamp(1.25rem, 3vw, 2.4rem);
}

.statStrip strong {
  color: var(--docs-lime);
  display: block;
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  font-size: 1.05rem;
  font-weight: 680;
}

.statStrip li span {
  color: var(--docs-muted);
  display: block;
  font-size: 0.72rem;
  margin-top: 0.35rem;
}

.statStrip > [data-docs-rule],
.section > [data-docs-rule],
.timeline > [data-docs-rule],
.finalCta > [data-docs-rule] {
  background: var(--section-accent, var(--docs-accent));
  bottom: -1px;
  height: 2px;
  left: 0;
  position: absolute;
  width: 100%;
}

.section {
  --section-accent: var(--docs-accent);
  --section-background: var(--docs-canvas);
  --section-foreground: var(--docs-foreground);
  --section-line: var(--docs-line);
  --section-muted: var(--docs-muted);
  background: var(--section-background);
  border-inline: 1px solid var(--section-line);
  color: var(--section-foreground);
  display: grid;
  gap: clamp(3rem, 7vw, 8rem);
  grid-template-areas: "copy visual";
  grid-template-columns: minmax(0, 0.78fr) minmax(440px, 1.22fr);
  margin: 0 auto;
  max-width: 1600px;
  min-height: 720px;
  padding: clamp(5.5rem, 10vw, 10rem) clamp(1.5rem, 6vw, 7rem);
  position: relative;
}

.section[data-layout="visual-first"] {
  grid-template-areas: "visual copy";
  grid-template-columns: minmax(440px, 1.22fr) minmax(0, 0.78fr);
}

.section[data-layout="stacked"] {
  grid-template-areas:
    "copy"
    "visual";
  grid-template-columns: 1fr;
}

.section[data-tone="paper"] {
  --section-accent: var(--docs-blue);
  --section-background: var(--docs-paper);
  --section-foreground: var(--docs-ink);
  --section-line: #c9c1b5;
  --section-muted: #655f56;
}

.section[data-tone="coral"] {
  --section-accent: var(--docs-ink);
  --section-background: var(--docs-accent);
  --section-foreground: var(--docs-ink);
  --section-line: color-mix(in srgb, var(--docs-ink) 35%, transparent);
  --section-muted: #54271c;
}

.section[data-tone="blue"] {
  --section-accent: var(--docs-lime);
  --section-background: var(--docs-blue);
  --section-foreground: var(--docs-paper-bright);
  --section-line: color-mix(in srgb, var(--docs-paper-bright) 28%, transparent);
  --section-muted: #d5dcff;
}

.section[data-tone="lime"] {
  --section-accent: var(--docs-blue);
  --section-background: var(--docs-lime);
  --section-foreground: var(--docs-ink);
  --section-line: color-mix(in srgb, var(--docs-ink) 35%, transparent);
  --section-muted: #3f4f1f;
}

.sectionCopy {
  align-self: center;
  grid-area: copy;
  max-width: 600px;
}

.sectionKicker {
  align-items: center;
  color: var(--section-muted);
  display: flex;
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  font-size: 0.68rem;
  font-weight: 650;
  gap: 0.8rem;
  letter-spacing: 0.045em;
  margin-bottom: 1.8rem;
  text-transform: uppercase;
}

.sectionKicker strong {
  border: 1px solid var(--section-line);
  color: var(--section-accent);
  font-size: 0.67rem;
  padding: 0.42rem 0.5rem;
}

.section h2,
.timeline h2,
.finalCta h2 {
  font-size: clamp(3.15rem, 5.7vw, 6.5rem);
  font-weight: 680;
  letter-spacing: -0.07em;
  line-height: 0.92;
  margin: 0;
  text-wrap: balance;
}

.sectionDescription {
  color: var(--section-muted);
  font-size: clamp(1rem, 1.25vw, 1.17rem);
  line-height: 1.65;
  margin-top: 1.8rem;
  max-width: 560px;
}

.sectionCopy > .textAction {
  margin-top: 1.5rem;
}

.sectionVisual {
  align-self: center;
  grid-area: visual;
  min-width: 0;
}

.demoFrame {
  background: var(--docs-surface);
  border: 1px solid var(--docs-line);
  box-shadow: 12px 14px 0 var(--section-accent);
  color: var(--docs-foreground);
  min-height: 420px;
  overflow: hidden;
  position: relative;
}

.demoFrame > header {
  align-items: center;
  border-bottom: 1px solid var(--docs-line);
  color: var(--docs-muted);
  display: flex;
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  font-size: 0.64rem;
  justify-content: space-between;
  min-height: 48px;
  padding: 0 1rem;
  text-transform: uppercase;
}

.demoBody {
  min-height: inherit;
  position: relative;
}

.timeline {
  border-inline: 1px solid var(--docs-line);
  margin: 0 auto;
  max-width: 1600px;
  padding: clamp(6rem, 10vw, 10rem) clamp(1.5rem, 6vw, 7rem);
  position: relative;
}

.timeline > header {
  display: grid;
  gap: 1.2rem;
  grid-template-columns: minmax(100px, 0.25fr) minmax(0, 0.75fr);
  margin-bottom: clamp(4rem, 8vw, 7rem);
}

.timeline > header > span {
  color: var(--docs-accent);
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  font-size: 0.68rem;
  letter-spacing: 0.045em;
  padding-top: 0.6rem;
  text-transform: uppercase;
}

.timeline > header > div {
  color: var(--docs-muted);
  grid-column: 2;
  line-height: 1.65;
  max-width: 620px;
}

.timeline ol {
  border-top: 1px solid var(--docs-line);
  list-style: none;
  margin: 0;
  padding: 0;
}

.timeline li {
  border-bottom: 1px solid var(--docs-line);
}

.timeline li > a,
.timeline li > div {
  display: grid;
  gap: 1.4rem;
  grid-template-columns: minmax(110px, 0.24fr) minmax(180px, 0.34fr) 1fr;
  padding: 1.8rem 0;
}

.timeline li > a {
  transition:
    background 160ms ease,
    padding 160ms ease;
}

.timeline li > a:hover {
  background: var(--docs-surface);
  padding-inline: 1.2rem;
}

.timeline time {
  color: var(--docs-accent);
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  font-size: 0.68rem;
  padding-top: 0.2rem;
}

.timeline li strong {
  font-size: 1rem;
}

.timeline li div div,
.timeline li a div {
  color: var(--docs-muted);
  font-size: 0.9rem;
  line-height: 1.6;
}

.finalCta {
  --section-accent: var(--docs-blue);
  --section-line: color-mix(in srgb, var(--docs-ink) 35%, transparent);
  --section-muted: #3f4f1f;
  background: var(--docs-lime);
  border-inline: 1px solid var(--section-line);
  color: var(--docs-ink);
  display: grid;
  grid-template-columns: minmax(0, 0.64fr) minmax(360px, 0.36fr);
  margin: 0 auto;
  max-width: 1600px;
  min-height: 740px;
  overflow: hidden;
  padding: clamp(6rem, 10vw, 10rem) clamp(1.5rem, 6vw, 7rem);
  position: relative;
}

.finalCopy {
  align-self: center;
  max-width: 850px;
  position: relative;
  z-index: 2;
}

.finalCopy > span {
  font-family:
    var(--font-docs-mono), "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}

.finalCta h2 {
  margin-top: 1.65rem;
}

.finalCta h2 em {
  color: var(--docs-blue);
}

.finalCopy > div:not(.finalActions) {
  color: var(--section-muted);
  font-size: 1.08rem;
  line-height: 1.62;
  margin-top: 1.7rem;
  max-width: 590px;
}

.finalActions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-top: 2rem;
}

.finalActions .primaryAction {
  background: var(--docs-ink);
  color: var(--docs-paper-bright) !important;
}

.finalActions .primaryAction:hover {
  background: var(--docs-blue);
  box-shadow: 7px 7px 0 var(--docs-accent);
}

.finalDecoration {
  align-self: center;
  justify-self: stretch;
  min-width: 0;
  position: relative;
  z-index: 1;
}

.footer {
  align-items: end;
  border-inline: 1px solid var(--docs-line);
  display: flex;
  justify-content: space-between;
  margin: 0 auto;
  max-width: 1600px;
  padding: 3rem clamp(1.5rem, 4vw, 4rem);
}

.footer > div > p {
  color: var(--docs-muted);
  font-size: 0.72rem;
  margin-top: 1rem;
}

.footer nav {
  display: flex;
  flex-wrap: wrap;
  font-size: 0.74rem;
  gap: 1.4rem;
}

.footer nav a:hover {
  color: var(--docs-lime);
}

@media (max-width: 1040px) {
  .hero {
    grid-template-columns: 1fr;
    padding-bottom: 7rem;
  }

  .heroCopy {
    max-width: 760px;
  }

  .heroVisual {
    min-height: 560px;
  }

  .section,
  .section[data-layout="visual-first"] {
    gap: 4rem;
    grid-template-areas:
      "copy"
      "visual";
    grid-template-columns: 1fr;
  }

  .sectionCopy {
    max-width: 760px;
  }

  .finalCta {
    gap: 3.5rem;
    grid-template-columns: 1fr;
  }

  .finalDecoration {
    max-height: 340px;
  }
}

@media (max-width: 700px) {
  .headerInner {
    height: 62px;
    padding-inline: 1rem;
  }

  .brand {
    font-size: 0.86rem;
  }

  .brand code {
    display: none;
  }

  .navigation {
    gap: 0.8rem;
    overflow-x: auto;
  }

  .navigation > a:not(.repositoryLink) {
    display: none;
  }

  .repositoryLink {
    min-height: 40px !important;
    padding-inline: 0.8rem;
  }

  .hero {
    border-inline: 0;
    gap: 3rem;
    min-height: calc(100svh - 62px);
    padding: 4.2rem 1.25rem 6.5rem;
  }

  .hero::before {
    inset-inline: 1.25rem;
  }

  .heroCopy {
    padding-left: 0;
  }

  .hero h1 {
    font-size: clamp(3.5rem, 18vw, 5.15rem);
  }

  .heroVisual {
    box-shadow: 8px 9px 0 var(--docs-accent);
    min-height: 470px;
    transform: none;
  }

  .scrollCue {
    left: 1.25rem;
    transform: none;
  }

  .installCommand {
    width: 100%;
  }

  .installCommand code {
    flex: 1;
    text-align: left;
  }

  .installCopy {
    min-width: 4rem;
  }

  .statStrip {
    border-inline: 0;
    overflow-x: auto;
  }

  .statStrip ul {
    display: flex;
    min-width: max-content;
  }

  .statStrip li {
    min-width: 180px;
  }

  .section {
    border-inline: 0;
    min-height: auto;
    padding: 6.5rem 1.25rem;
  }

  .section h2,
  .timeline h2,
  .finalCta h2 {
    font-size: clamp(3rem, 15vw, 4.6rem);
  }

  .demoFrame {
    box-shadow: 7px 8px 0 var(--section-accent);
    min-height: 390px;
  }

  .timeline {
    border-inline: 0;
    padding: 6.5rem 1.25rem;
  }

  .timeline > header {
    display: block;
  }

  .timeline > header h2 {
    margin-top: 1.4rem;
  }

  .timeline > header > div {
    margin-top: 1.4rem;
  }

  .timeline li > a,
  .timeline li > div {
    gap: 0.65rem;
    grid-template-columns: 1fr;
    padding-block: 1.5rem;
  }

  .timeline li > a:hover {
    margin-inline: -1.25rem;
    padding-inline: 1.25rem;
  }

  .finalCta {
    border-inline: 0;
    min-height: auto;
    padding: 6.5rem 1.25rem;
  }

  .finalDecoration {
    display: none;
  }

  .finalActions {
    align-items: stretch;
    flex-direction: column;
  }

  .finalActions .primaryAction {
    justify-content: center;
  }

  .footer {
    align-items: start;
    border-inline: 0;
    flex-direction: column;
    gap: 2rem;
    padding: 3rem 1.25rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .root *,
  .root *::after,
  .root *::before {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}
